          "detailMarkdown": "## 7786 東方風能 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（64 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 2、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 1Q26 營收 17.73 億元，年增 53.8%。\n- 1Q26 營業利益 2.80 億元，年增 19.7%；毛利 3.51 億元，年增 19.4%。\n- 1Q26 稅後淨利 2.11 億元，年減 17.3%；EPS 為 1.20 元。\n- 期末資產總額 166.09 億元，較去年同期顯著增加，主要來自非流動資產擴張。\n- 現金及約當現金 6.95 億元，較去年同期減少；應收帳款、預付款與其他非流動資產增加。\n- 股本為 17.54 億元，權益總計 100.60 億元；轉錄提及 2025 年現金股利配發率提升，簡報圖表顯示 2025 年配發率 50.4%。\n\n### 展望與成長利基\n- 2Q–3Q26 隨施工高峰到來，船隊利用率預期提升。\n- 改裝後的佈纜船將投入高毛利專案，毛利率預期回升至去年旺季水準。\n- 通訊海纜專案將進入主要工程認列階段，並預計於 3Q26 完成建置。\n- 2026 年底至 2028 年新增 5 艘大型工程船，將加速船隊升級並提高高毛利業務占比。\n- 2027–2029 年規模效益可望逐步顯現；簡報與轉錄均提到國際市場與跨能源應用擴張。\n\n### 產品、客戶與市場位置\n- 簡報與轉錄皆強調公司正由本土風電海事工程，轉向具全球競爭力的亞太離岸能源平台。\n- 2027–2029 年規模效益可望逐步顯現；簡報與轉錄均提到國際市場與跨能源應用擴張。\n- 簡報明確揭露前瞻性資訊存在市場需求、價格波動、國際情勢、政策法規與金融環境變動風險。\n- 需人工確認：簡報與轉錄對 2030 年離岸風電 / 通訊海纜 / 天然氣能源占比表述略有差異，應以原始簡報圖表為主。\n- 需人工確認：轉錄提到「資料中心用電量至少增加一倍以上」等外部研究敘述，簡報中對應為 BNEF 預測與 AI 需求成長，具體數字來源口徑需再核對。\n\n### 風險與不確定性\n- 簡報明確揭露前瞻性資訊存在市場需求、價格波動、國際情勢、政策法規與金融環境變動風險。\n- 轉錄提到離岸風電產業受「電價是否上升」影響，部分開發商可能退場，顯示產業商業模式仍具不確定性。\n- 匯率波動對業外損益有影響，1Q26 業外收支為 -13 百萬元，轉錄亦提及年初匯率波動較大。\n- 船舶改裝期間會影響階段性稼動與毛利表現。\n- 大型專案認列時點、施工進度與完工比例法認列節奏，可能使季間表現波動。\n- 需人工確認：轉錄提到「2025 年 EPS 達到 11.1 億元」，應為「2025 年 EPS 11.1 元」或其他獲利指標，與語意不一致。\n- 需人工確認：轉錄提到「現金股利總額 9.8 億元」與簡報僅顯示配發率圖表，未見同頁完整數字。\n- 需人工確認：轉錄多次將部分船舶名稱、公司名稱誤聽為「highlight程式」「DP Ocean」「DESOS」「VIP」等；簡報對應應為 cable-laying vessel、DeepOcean、Vestas。\n\n### Q&A 與管理層口氣\n- 改裝後的佈纜船將投入高毛利專案，毛利率預期回升至去年旺季水準。\n\n### 評分利基點\n- 加分主因：1Q26 營收成長主要來自離岸風場工程需求優於預期，以及通訊海纜專案依完工比例法認列收入。；管理層表示，第一季雖為產業淡季，但整體需求動能仍強。；第二、三季預期進入海事工程施工高峰，船隊將全面投入營運。。\n- 扣分或保留：簡報明確揭露前瞻性資訊存在市場需求、價格波動、國際情勢、政策法規與金融環境變動風險。；轉錄提到離岸風電產業受「電價是否上升」影響，部分開發商可能退場，顯示產業商業模式仍具不確定性。；匯率波動對業外損益有影響，1Q26 業外收支為 -13 百萬元，轉錄亦提及年初匯率波動較大。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
