          "detailMarkdown": "## 6177 達麗 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（57 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 1、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2023~2025 年營收分別為 154.26 億、123.20 億、95.31 億元，2026Q1 營收為 48.44 億元。\n- 2025 年稅後淨利為 18.09 億元，EPS 為 3.84 元；2026Q1 稅後淨利 16.74 億元，EPS 3.53 元。\n- 2026Q1 毛利率為 50.06%，高於 2025 年的 32.32%；簡報與轉錄均提及主因與台南個案認列有關。\n- 負債比 2026Q1 為 72.12%，公司表示希望逐步降至 70% 以下。\n- 2025 年現金股利為 3.00 元/股，股利發放率 78.12%；公司章程修訂後，年度股利分配不得低於可分配盈餘 60%，且現金股利不低於股東紅利總額 60%。\n\n### 展望與成長利基\n- 2026 年預計推案金額近 233 億元，包含台南平實段 88 億、台中洲際段 75 億、新竹台肥段 70 億。\n- 2028 年以後儲備案量合計 1,439 億元，主要集中在都更、公辦都更、捷運聯開與自地自建案。\n- 高雄左營區部後段公辦都更案為關鍵案源：一期投資金額 239 億元、二期投資金額 302 億元，簡報稱 2028 年中起陸續開發。\n- 公司持續主張以首購、首換與交通/TOD、產業、新興重劃區作為購地與開發策略。\n- 對市場看法偏向穩健：認為預售屋房價受成本支撐、短期下跌空間有限；央行第二戶貸款成數回調與逐步回歸銀行自主管理，有助緩解申貸壓力。\n\n### 產品、客戶與市場位置\n- 轉錄中提到公司對北高雄左營案的區域想像較為積極，並多次提及公辦都更與聯開案對中長期成長的重要性。\n- 對市場看法偏向穩健：認為預售屋房價受成本支撐、短期下跌空間有限；央行第二戶貸款成數回調與逐步回歸銀行自主管理，有助緩解申貸壓力。\n- 公司提及前瞻性資訊受市場需求、政策法令、原物料成本與總體經濟變動影響，實際結果可能與預期不同。\n- 房市銷售與貸款環境仍存在政策與市場不確定性，特別是大型開發案的推案節奏與認列時間。\n\n### 風險與不確定性\n- 營建成本仍在上行，簡報指出 115 年 4 月營造工程物價指數年增率達 4.46%，為 112 年以來最高單月增幅。\n- 材料價格波動明顯，包括鋼筋、土石方/廢棄物、PVC 管、鋁料、電線及石化相關材料。\n- 公司提及前瞻性資訊受市場需求、政策法令、原物料成本與總體經濟變動影響，實際結果可能與預期不同。\n- 房市銷售與貸款環境仍存在政策與市場不確定性，特別是大型開發案的推案節奏與認列時間。\n- 轉錄中對部分營建材料漲幅的口語敘述較為零散，需與簡報數字交叉確認。\n- **需人工確認**：轉錄中出現公司名稱為「達力建設事業股份有限公司」，簡報為「達麗建設 (6177)」。\n- **需人工確認**：轉錄提到「今年收購了伊拉甲型營造廠、定層營造」等，簡報未揭露相關併購資訊。\n- **需人工確認**：轉錄中部分人名/地名口語辨識與簡報略有差異，例如「李堯方／李堯芳」、「台星證券／台新證券」、「復活段／部後段」。\n\n### Q&A 與管理層口氣\n- 簡報聚焦經營績效、個案介紹、未來展望與 Q&A，主軸以房地產開發案進度、推案規劃與成本環境為主。\n- 2026Q1 毛利率為 50.06%，高於 2025 年的 32.32%；簡報與轉錄均提及主因與台南個案認列有關。\n- 對市場看法偏向穩健：認為預售屋房價受成本支撐、短期下跌空間有限；央行第二戶貸款成數回調與逐步回歸銀行自主管理，有助緩解申貸壓力。\n- 營建成本仍在上行，簡報指出 115 年 4 月營造工程物價指數年增率達 4.46%，為 112 年以來最高單月增幅。\n- 公司提及前瞻性資訊受市場需求、政策法令、原物料成本與總體經濟變動影響，實際結果可能與預期不同。\n\n### 評分利基點\n- 加分主因：2026 年重要事件包括：高雄左營區部後段公辦都更案獲選最優申請人、公告 2025 EPS 3.84 元、擬配發現金股利 3.00 元/股。；公司強調開發方向以都更案、聯合開發案為核心，並延伸至高雄以外的核心都會區。；轉錄中提到公司對北高雄左營案的區域想像較為積極，並多次提及公辦都更與聯開案對中長期成長的重要性。。\n- 扣分或保留：營建成本仍在上行，簡報指出 115 年 4 月營造工程物價指數年增率達 4.46%，為 112 年以來最高單月增幅。；材料價格波動明顯，包括鋼筋、土石方/廢棄物、PVC 管、鋁料、電線及石化相關材料。；公司提及前瞻性資訊受市場需求、政策法令、原物料成本與總體經濟變動影響，實際結果可能與預期不同。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
