          "detailMarkdown": "## 7769 鴻勁 深度法說分析\n\n### 一頁結論\n- 展望評價：正面看好（71 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 3、保守訊號 0。\n- 判讀：正向訊號較集中，通常代表公司對需求、訂單或產品組合的能見度較高。仍要確認這些動能是否能轉成營收與毛利。 \n\n### 營運與財務重點\n- 2026Q1 營收約 **107.25 億元**，較 2025 年各季明顯增長；毛利率 **56.24%**，EPS **25.7 元**。\n- Q1 財務表現摘要：營業毛利率約 **56.24%**、營業淨利率約 **43.1%**，獲利能力維持高檔。\n- 簡報數據顯示 2025Q1 營收約 **59.13 億元**、2025 全年營收約 **302.71 億元**；2026Q1 營收達 **107.25 億元**。\n- 訂單應用別分布以 **AI/HPC/ASIC 78%** 為主，其次為 **汽車 9%**、**Mobile AP 通訊 9%**、**3C 3%**、**Memory/MEMS 1%**。\n- 冷板（Cold Plate）業務出貨採認列營收模式，管理層提到 2026 年冷板營收占比可望高於過去平均。\n\n### 展望與成長利基\n- AI/HPC/ASIC 需求仍為主要成長動能，管理層提到下半年至明年仍可見多個客戶專案推進。\n- FT 方面，CSP 客戶新 CPU 訂單、以色列客戶 ASIC Switch、以及美系 EV 大廠 AI 晶片案，皆被視為後續出貨重點。\n- SLT 方面，下一代 CPU、GPU 與 CSP 客戶 10kW 以上高功耗產品的測試需求持續開發中。\n- CPO/光電同測（OE）預計在 2026H2 進入較完整的工程驗證與釋出階段，量產時程偏向 2027 年初。\n- 產能規劃方面，新購廠房可增加約 **20%–30%** 空間，管理層提到內部對 2027 年的產能提升目標約 **50%**。\n\n### 產品、客戶與市場位置\n- 管理層強調 Q1 需求主要集中於 AI/HPC/ASIC，高階測試與散熱控制相關產品線貢獻提升。\n- Q&A 主要聚焦在產能擴充、GPU/CPU 專案時程、CPO insertion、歐洲車用客戶與 Burn-in Oven 相關更新。\n- 訂單應用別分布以 **AI/HPC/ASIC 78%** 為主，其次為 **汽車 9%**、**Mobile AP 通訊 9%**、**3C 3%**、**Memory/MEMS 1%**。\n- AI/HPC/ASIC 需求仍為主要成長動能，管理層提到下半年至明年仍可見多個客戶專案推進。\n- FT 方面，CSP 客戶新 CPU 訂單、以色列客戶 ASIC Switch、以及美系 EV 大廠 AI 晶片案，皆被視為後續出貨重點。\n- SLT 方面，下一代 CPU、GPU 與 CSP 客戶 10kW 以上高功耗產品的測試需求持續開發中。\n\n### 風險與不確定性\n- 高功耗產品（如 10kW 以上）測試與溫控技術仍在開發與驗證中，時程存在不確定性。\n- CPO insertion 4/5、光電同測與 throughput 最佳化仍需工程數據驗證，量產導入時點尚未完全定案。\n- 產能擴充雖已啟動，但新廠房需約一季完成廠務與人力配置，短期內仍有爬坡期。\n- 海外客戶專案（美國、歐洲、以色列）多處於送樣、驗證、工程測試或排程確認階段，後續變化仍可能影響認列節奏。\n- 管理層多次強調 forward-looking statements 受市場需求、競爭、法規與客戶排程影響。\n- **需人工確認：** 轉錄中多次提到「宏進精密」，應為公司名稱的口語轉述；簡報英文為 **HON. PRECISION, INC.**，中文公司名與中譯可能需再核對。\n- **需人工確認：** 簡報第 6 頁財務表格中的欄位排列與數字對齊不甚清楚，轉錄提到的營業淨利額 **53.6 億** 與簡報表格呈現需再核對。\n- **需人工確認：** 轉錄提到 2026Q1 EPS 為 **25.7 元**，簡報第 5 頁顯示 **25.70**，數字一致但格式需確認。\n\n### Q&A 與管理層口氣\n- 會中多次提及產能擴充、CPO/光電同測、SLT、FT、冷板等新案進展。\n- Q&A 主要聚焦在產能擴充、GPU/CPU 專案時程、CPO insertion、歐洲車用客戶與 Burn-in Oven 相關更新。\n- 2026Q1 營收約 **107.25 億元**，較 2025 年各季明顯增長；毛利率 **56.24%**，EPS **25.7 元**。\n- Q1 財務表現摘要：營業毛利率約 **56.24%**、營業淨利率約 **43.1%**，獲利能力維持高檔。\n- 訂單應用別分布以 **AI/HPC/ASIC 78%** 為主，其次為 **汽車 9%**、**Mobile AP 通訊 9%**、**3C 3%**、**Memory/MEMS 1%**。\n- FT 方面，CSP 客戶新 CPU 訂單、以色列客戶 ASIC Switch、以及美系 EV 大廠 AI 晶片案，皆被視為後續出貨重點。\n\n### 評分利基點\n- 加分主因：管理層強調 Q1 需求主要集中於 AI/HPC/ASIC，高階測試與散熱控制相關產品線貢獻提升。；會中多次提及產能擴充、CPO/光電同測、SLT、FT、冷板等新案進展。；Q&A 主要聚焦在產能擴充、GPU/CPU 專案時程、CPO insertion、歐洲車用客戶與 Burn-in Oven 相關更新。。\n- 扣分或保留：高功耗產品（如 10kW 以上）測試與溫控技術仍在開發與驗證中，時程存在不確定性。；CPO insertion 4/5、光電同測與 throughput 最佳化仍需工程數據驗證，量產導入時點尚未完全定案。；產能擴充雖已啟動，但新廠房需約一季完成廠務與人力配置，短期內仍有爬坡期。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
