          "detailMarkdown": "## 3529 力旺 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（65 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 3、保守訊號 1。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- Q1 2026 營收 **NT$1,093,993 千元**，QoQ **+4.4%**、YoY **+20.0%**。\n- 營業利益 **NT$662,377 千元**，營業利益率 **60.5%**；稅後淨利 **NT$596,250 千元**，EPS **NT$7.98**。\n- 授權金（Licensing）為 **NT$381,035 千元**，QoQ **+9.9%**；權利金（Royalty）為 **NT$712,958 千元**，QoQ **+1.6%**。\n- 產品別來看，Q1 營收占比以 **NeoFuse 59.8%** 為主，其次為 **NeoBit 20.0%、PUF-Based 12.2%、MTP 8.0%**。\n- 權利金來源以 **12 吋晶圓 66.3%** 為主，8 吋占 **33.7%**；轉錄與簡報一致。\n\n### 展望與成長利基\n- 授權金成長動能來自 **foundry 與 fabless 客戶數增加**、以及 **單一 license ASP 提升**。\n- 權利金成長動能來自 **既有產品升級、新 advanced-node 應用、高階節點 ASP 提升、PUF 權利金擴大、MTP 比重增加**。\n- 新技術方向包含 **sub-2nm OTP/PUF-based hardware security** 與 **1T Flash（NeoFlash）**，可延伸至 embedded 與 standalone 應用。\n- 業務平台拓展聚焦 **Chiplet Security、Data Center Caliptra、Root of Trust / CPU、HSM Edge Server**。\n- Q&A 補充提到，成長來源還包括 **OLED DDI、PINMIG、手機 modem、AICPU、BMC、SSD controller、CXL、DRAM module** 等導入。\n\n### 產品、客戶與市場位置\n- 會議主軸聚焦 **Q1 2026 營運表現、AI/硬體資安趨勢、1T Flash 與系統級安全方案**。\n- 轉錄內容提到 Q1 延續高檔營運，並受惠於 **3nm、AI server CPU、SRAM repair、高速介面、PUF/OTP** 等應用擴張。\n- 簡報亦呈現未來成長重點包含 **advanced-node、AI、security、next-generation Flash**。\n- 產品別來看，Q1 營收占比以 **NeoFuse 59.8%** 為主，其次為 **NeoBit 20.0%、PUF-Based 12.2%、MTP 8.0%**。\n- 授權金成長動能來自 **foundry 與 fabless 客戶數增加**、以及 **單一 license ASP 提升**。\n- 權利金成長動能來自 **既有產品升級、新 advanced-node 應用、高階節點 ASP 提升、PUF 權利金擴大、MTP 比重增加**。\n\n### 風險與不確定性\n- 轉錄與簡報皆提到一般性風險：**晶圓價格波動、需求變化、技術迭代、客戶 tape-out 延遲/失敗、權利金談判與執行、智慧財產訴訟、景氣循環**。\n- Q&A 提到 Q1 權利金短期受到 **某台灣 foundry 客戶出售/產線轉移** 影響，屬暫時性干擾。\n- 轉錄指出成熟製程價格調整、產能重分配與 AI/先進製程擠壓成熟製程資源，存在供應鏈結構變動不確定性。\n- 新業務如 **HSM / security as a service / 1T Flash** 仍處於開發、整合或驗證階段，商業化節奏未完全揭露。\n- 未揭露：對各項新業務的具體量產時點與貢獻規模。\n- **Q1 財報數字**：簡報表格與轉錄一致，包含營收、營業利益、淨利、EPS、ROE。\n- **授權金/權利金分拆**：簡報與轉錄一致；Q1 營收結構為 **Licensing 34.8% / Royalty 65.2%**。\n- **12 吋/8 吋權利金占比**：簡報與轉錄一致；12 吋 **66.3%**、8 吋 **33.7%**。\n\n### Q&A 與管理層口氣\n- **Q1 權利金季減原因**：管理層表示主要因 **台灣某 foundry 客戶產線/出售調整**，且 Q1 仍反映去年 Q4 出貨與去年代工價格，預期影響屬暫時性。\n- **SRAM repair / AI 相關案子**：已與 **Siemens** 合作整合方案，並有多個 AI-related design-in，集中在 **AI data center processor、memory controller、CSO/CSL 類晶片**。\n- **1T NeoFlash**：採用移除 select transistor 的架構，能支援 **embedded/standalone flash**，並可延伸 **NOR、2D NAND、MLC**；目前進入實質開發並與多家 foundry/fabless 合作。\n- **Intel Foundry 合作**：聚焦 **advanced-node OTP 與 PUF-based security IP**，並推進至 **Intel 18A**。\n- **VeraRubin / OCP / Caliptra**：管理層說明 OTP、PUF 已被納入相關規範，技術已導入 **CPU、BMC、SSD Controller、CXL Controller、networking** 等。\n- **系統級硬體安全**：公司正在發展 **HSM、PKI 整合、signing-as-a-service**；短期重技術驗證，中長期看平台授權與服務模式。\n- 未揭露：Q&A 中各問題對應的完整逐字稿正式版與時間點。\n\n### 評分利基點\n- 加分主因：管理層強調，公司正由 **IP 授權商** 延伸至 **系統層級硬體安全解決方案提供者**。；轉錄內容提到 Q1 延續高檔營運，並受惠於 **3nm、AI server CPU、SRAM repair、高速介面、PUF/OTP** 等應用擴張。；簡報亦呈現未來成長重點包含 **advanced-node、AI、security、next-generation Flash**。。\n- 扣分或保留：轉錄與簡報皆提到一般性風險：**晶圓價格波動、需求變化、技術迭代、客戶 tape-out 延遲/失敗、權利金談判與執行、智慧財產訴訟、景氣循環**。；Q&A 提到 Q1 權利金短期受到 **某台灣 foundry 客戶出售/產線轉移** 影響，屬暫時性干擾。；轉錄指出成熟製程價格調整、產能重分配與 AI/先進製程擠壓成熟製程資源，存在供應鏈結構變動不確定性。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
