          "detailMarkdown": "## 5347 世界 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（64 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 2、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 第1季營收 **125.32 億元**，較去年同期 **+4.9%**、較前一季 **-0.5%**。\n- 毛利率 **29.3%**，營業利益率 **16.7%**，稅後淨利率 **17.3%**。\n- 期末現金與金融資產 **465.37 億元**；歸屬母公司業主權益 **684.16 億元**。\n- 第1季營業活動淨現金流入 **114.32 億元**；資本支出約 **252.80 億元**（轉錄提及，詳見交叉核對）。\n- 財務指標：應收帳款週轉天數 **51 天**、存貨週轉天數 **74 天**、負債比 **57%**、流動比率 **149%**。\n\n### 展望與成長利基\n- 第2季：晶圓出貨量預期季增 **11%~13%**，ASP 季增 **2%~4%**，以匯率 **31.3** 為假設，毛利率 **31%~33%**。\n- 管理層表示 2026 年半導體需求整體仍可望維持「穩健成長」。\n- AI server 相關營收占比由去年 **low single digit** 提升至今年 **low double digit**，並提到 2027 年仍有延續成長機會。\n- 新加坡廠（VSMC）與 12 吋產線的建置/量產時程持續推進，對 2027 年後營運結構有影響。\n- 公司長期營業費用率目標仍維持在營收 **10% 以內**，但 2026 年預估仍在較高區間。\n\n### 產品、客戶與市場位置\n- 第1季晶圓出貨量約 **64.2 萬片**，季增約 **3%**；產品平均銷售單價季減約 **4%**。\n- 管理層提到 AI 相關需求帶動 server 等應用成長，並延伸至 2027 年。\n- 管理層表示 2026 年半導體需求整體仍可望維持「穩健成長」。\n- AI server 相關營收占比由去年 **low single digit** 提升至今年 **low double digit**，並提到 2027 年仍有延續成長機會。\n- 管理層提及全球 GDP、戰爭、通膨、能源價格等外部變數，可能影響半導體需求與成本。\n- 產品組合與客戶需求變動，可能影響 ASP、稼動率與獲利結構。\n\n### 風險與不確定性\n- 簡報載明前瞻性陳述受已知與未知風險、不確定性影響。\n- 管理層提及全球 GDP、戰爭、通膨、能源價格等外部變數，可能影響半導體需求與成本。\n- 新加坡 12 吋產線在 2027~2028 年建置/爬坡期間，對毛利率與折舊費用仍有壓力。\n- 產品組合與客戶需求變動，可能影響 ASP、稼動率與獲利結構。\n- 地緣政治與供應鏈分散需求，可能牽動產能配置與投資節奏。\n- 轉錄提到第1季晶圓出貨量為 **62.2 萬片**，與簡報 **64.2 萬片** 不一致；**需人工確認**。\n- 轉錄提到期末現金餘額 **443.53 億元**，簡報為 **465.37 億元**；差異顯著，**需人工確認**。\n- 轉錄提到第1季資本支出 **252.80 億元**，簡報現金流表顯示購置不動產、廠房及設備與無形資產 **252.80 億元**，數字一致，但與管理層口述脈絡可再確認。\n\n### Q&A 與管理層口氣\n- 公司說明第1季毛利率回升至 **29.3%**，主因為去年第4季地震一次性影響消退與匯率有利。\n- 第2季營運展望為：出貨量季增 **11%~13%**，ASP 季增 **2%~4%**，毛利率估介於 **31%~33%**。\n- 毛利率 **29.3%**，營業利益率 **16.7%**，稅後淨利率 **17.3%**。\n- 第2季：晶圓出貨量預期季增 **11%~13%**，ASP 季增 **2%~4%**，以匯率 **31.3** 為假設，毛利率 **31%~33%**。\n- 公司長期營業費用率目標仍維持在營收 **10% 以內**，但 2026 年預估仍在較高區間。\n- 管理層提及全球 GDP、戰爭、通膨、能源價格等外部變數，可能影響半導體需求與成本。\n\n### 評分利基點\n- 加分主因：管理層提到 AI 相關需求帶動 server 等應用成長，並延伸至 2027 年。；管理層表示 2026 年半導體需求整體仍可望維持「穩健成長」。；AI server 相關營收占比由去年 **low single digit** 提升至今年 **low double digit**，並提到 2027 年仍有延續成長機會。。\n- 扣分或保留：簡報載明前瞻性陳述受已知與未知風險、不確定性影響。；管理層提及全球 GDP、戰爭、通膨、能源價格等外部變數，可能影響半導體需求與成本。；新加坡 12 吋產線在 2027~2028 年建置/爬坡期間，對毛利率與折舊費用仍有壓力。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
