          "detailMarkdown": "## 6412 群電 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（57 分）。\n- 資料基礎：本次尚未取得可用語音轉錄，評估主要依簡報與 MOPS 擇要訊息；若後續補入影音，分數與判讀可再更新。\n- 評分依據：正向訊號 1、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026年第1季合併營收 **7,784百萬元**，季減 **0.8%**、年減 **7.8%**。\n- 2026年第1季毛利 **1,241百萬元**，毛利率 **15.9%**，較前季 **16.2%** 下滑 **0.3個百分點**。\n- 2026年第1季營業利益 **334百萬元**，營業利益率 **4.3%**；相較前季 **5.0%** 下降。\n- 2026年第1季稅後淨利 **404百萬元**，EPS **1.01元**；較去年同期 **403百萬元、EPS 1.01元**大致持平。\n- 產品別來看，PC **3,386百萬元**、Cloud and Smart Solutions **4,028百萬元**、Consumer Electronics **370百萬元**，其中消費電子年減較明顯。\n\n### 展望與成長利基\n- 簡報未揭露明確的季度或年度財測。\n- 公司展示全球產能配置，泰國廠建坪 **100K sqm**，顯示持續推進多點生產配置。\n- 產品組合維持穩定，顯示主要業務結構短期內未出現大幅變動。\n- 簡報以「Smarter, Greener, Zero Waste」作為結語，顯示後續仍聚焦智慧化與永續方向。\n- 未揭露更細部的訂單能見度、出貨動能或各產品線展望。\n\n### 產品、客戶與市場位置\n- 本次法說會主軸為**2026年第1季營運成果**，簡報主題聚焦於產品組合、合併損益、全球產能布局與股利政策。\n- 公司基本資料顯示，群電成立於 **2008/12/24**，2013年上市，核心產品為 **Switching Power Supply + Smart & Green Solutions**。\n- 2026年第1季產品組合大致穩定，營收仍以 **Cloud and Smart Solutions** 與 **PC** 為主。\n- 公司強調全球製造布局，包含中國與泰國據點，呈現**雙製造基地策略**。\n- 產品別來看，PC **3,386百萬元**、Cloud and Smart Solutions **4,028百萬元**、Consumer Electronics **370百萬元**，其中消費電子年減較明顯。\n- 產品組合維持穩定，顯示主要業務結構短期內未出現大幅變動。\n\n### 風險與不確定性\n- 簡報載明前瞻性聲明具有風險及不確定因素，實際結果可能與預測有重大差異。\n- 2026年第1季營收與獲利率較去年同期下滑，顯示需求或產品組合仍存在波動。\n- 消費電子營收年減 **8%**，該區塊後續表現可能仍具不確定性。\n- 全球生產據點分布於中國與泰國，供應鏈、地緣政治或產能調配風險未揭露細項。\n- 未揭露原物料、匯率、客戶集中度或庫存風險的具體影響。\n- 簡報第3頁市場值標示 **US$1.1Bn (May 4, 2026)**，與 2025 年營收 **NT$34.4B** 並列，無明顯衝突，但幣別與時點不同，屬資訊性對照。\n- 簡報第3頁員工人數為 **10,694 (Mar 31, 2026)**；若轉錄稿另有不同數字，需人工確認，惟本次未提供轉錄數字可比對。\n- 2026年第1季 EPS 計算基礎為 **400.769百萬股**，屬簡報揭露資訊。\n\n### Q&A 與管理層口氣\n- 轉錄稿未提供問答內容，故 **未揭露**。\n- 簡報列示近年獲獎，包括 Dell、Lenovo、HP、Gigabyte、Foxconn、Lexmark 等客戶相關獎項。\n- ESG與永續相關榮譽包括 TCSA、CDP A List、國家永續發展獎入選等。\n- 2025年現金股利為 **3.70元**，現金殖利率簡報標示 **4.2%**。\n- 2025年EPS為 **5.20元**，現金股利配發率 **71.2%**。\n\n### 評分利基點\n- 加分主因：公司強調全球製造布局，包含中國與泰國據點，呈現**雙製造基地策略**。；未揭露更細部的訂單能見度、出貨動能或各產品線展望。；2026年第1季營收與獲利率較去年同期下滑，顯示需求或產品組合仍存在波動。。\n- 扣分或保留：簡報載明前瞻性聲明具有風險及不確定因素，實際結果可能與預測有重大差異。；2026年第1季營收與獲利率較去年同期下滑，顯示需求或產品組合仍存在波動。；消費電子營收年減 **8%**，該區塊後續表現可能仍具不確定性。。\n- 可信度：尚缺語音轉錄，較難判斷管理層口氣、Q&A 細節與未寫在簡報中的展望。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
