          "detailMarkdown": "## 7631 聚賢研發-創 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（44 分）。\n- 資料基礎：本次尚未取得可用語音轉錄，評估主要依簡報與 MOPS 擇要訊息；若後續補入影音，分數與判讀可再更新。\n- 評分依據：正向訊號 0、保守訊號 1。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 2025 年營業收入 1,102,454 仟元，較 2024 年成長 29.58%；稅後淨利 126,452 仟元。\n- 2025 年毛利率 27.52%，較 2024 年 31.26% 下滑；營業利益率 13.93%，較前一年 16.32% 下降。\n- 2025 年 EPS 為 6.56 元，2024 年為 5.51 元，2023 年為 8.74 元。\n- 2025 年現金及約當現金 610,574 仟元，總資產 1,483,072 仟元，負債比 43.30%。\n- 2025 年研發費用 21,911 仟元，研發費用占營收比重 1.99%。\n\n### 展望與成長利基\n- 產業面聚焦 2026-2028 年半導體趨勢，包括區域在地化生產、供應鏈韌性、先進封裝與 Chiplet、第三代半導體材料、亞 2nm 節點、EUV 與 GAA。\n- 技術面持續推進綠色核心方案，如資源循環、低碳製程、氣體回收/純化/再利用、超臨界 CO2 清洗與萃取。\n- 產品面延伸雷射技術跨產業應用，並持續發展管路自動雷射焊接系統、管路抗結晶震動裝置、逆向工程等客製化方案。\n- 永續面持續結合創新與 ESG，簡報提及 2024 TSMC ESG Award、2025 TIE 銅牌與 2025 TCSA 永續報告銅獎。\n- 簡報未揭露具體營收指引、訂單能見度或資本支出規劃。\n\n### 產品、客戶與市場位置\n- 簡報聚焦三大面向：創新產品與專利、永續行動、以及 2023-2025 年財務表現。\n- 海外服務據點涵蓋日本、德國、新加坡、美國，台灣則布局於新竹、中部與南部科學園區。\n- 產業面聚焦 2026-2028 年半導體趨勢，包括區域在地化生產、供應鏈韌性、先進封裝與 Chiplet、第三代半導體材料、亞 2nm 節點、EUV 與 GAA。\n- 產品面延伸雷射技術跨產業應用，並持續發展管路自動雷射焊接系統、管路抗結晶震動裝置、逆向工程等客製化方案。\n- 簡報載明未發布財務預測，未來表現可能受技術演進、市場需求變化、原料價格波動、競爭行為與國際經濟景氣影響。\n- 半導體產業景氣與客戶投資節奏可能影響專案認列時點與毛利表現。\n\n### 風險與不確定性\n- 簡報載明未發布財務預測，未來表現可能受技術演進、市場需求變化、原料價格波動、競爭行為與國際經濟景氣影響。\n- 半導體產業景氣與客戶投資節奏可能影響專案認列時點與毛利表現。\n- 海外據點與跨產業應用推進，可能面臨區域營運、供應鏈協作與落地執行風險。\n- 新產品與專利布局存在研發不確定性，從開發到商轉仍可能受驗證與導入週期影響。\n- 簡報未揭露重大訴訟、法規或單一客戶依賴資訊。\n- **需人工確認：會議資訊寫明本次為「2025年度營運成果及公司營運現況暨未來展望」說明，但簡報封面為「2026 年第一季法人說明會」**，兩者期間表述不一致。\n- **需人工確認：中文簡報第 20 頁專利數字為「有效專利：發明4件、新型13件；審查中20件；總計37件」**，但同頁圓餅圖又顯示「有效專利 17 件、審查中 20 件」，且發明專利標示為 24 件，存在數字口徑不一致。\n- **需人工確認：英文版第 5 頁寫 IPO 日期為 2025/03/13、員工 170+、資本額 NT$201M；中文版第 5 頁僅顯示公司成立、上市日期、員工、資本額欄位但未填數字**，建議以原始公告再核對。\n\n### Q&A 與管理層口氣\n- 2025 年毛利率 27.52%，較 2024 年 31.26% 下滑；營業利益率 13.93%，較前一年 16.32% 下降。\n- 2025 年研發費用 21,911 仟元，研發費用占營收比重 1.99%。\n- 產業面聚焦 2026-2028 年半導體趨勢，包括區域在地化生產、供應鏈韌性、先進封裝與 Chiplet、第三代半導體材料、亞 2nm 節點、EUV 與 GAA。\n- 簡報未揭露具體營收指引、訂單能見度或資本支出規劃。\n- 海外據點與跨產業應用推進，可能面臨區域營運、供應鏈協作與落地執行風險。\n\n### 評分利基點\n- 加分主因：公司定位為「高科設備優化最佳服務商」，主軸涵蓋高科技廠房 MEP 機電、二次配系統裝機、氣體供應系統、零組件與耗材研發製造、售後技術支援。；會中強調以使用者需求與痛點為出發點，結合雷射光學、材料科學、自控與機械加工等跨域能力，發展客製化解決方案。；2025 年營業收入 1,102,454 仟元，較 2024 年成長 29.58%；稅後淨利 126,452 仟元。。\n- 扣分或保留：簡報載明未發布財務預測，未來表現可能受技術演進、市場需求變化、原料價格波動、競爭行為與國際經濟景氣影響。；半導體產業景氣與客戶投資節奏可能影響專案認列時點與毛利表現。；海外據點與跨產業應用推進，可能面臨區域營運、供應鏈協作與落地執行風險。。\n- 可信度：尚缺語音轉錄，較難判斷管理層口氣、Q&A 細節與未寫在簡報中的展望。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
