          "detailMarkdown": "## 2360 致茂 深度法說分析\n\n### 一頁結論\n- 展望評價：正面看好（78 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 4、保守訊號 0。\n- 判讀：正向訊號較集中，通常代表公司對需求、訂單或產品組合的能見度較高。仍要確認這些動能是否能轉成營收與毛利。 \n\n### 營運與財務重點\n- 2026Q1 營業收入：**118.59 億元**；本公司業主淨利：**38.64 億元**；EPS（基本）**9.12 元**。\n- 2026Q1 毛利：**74.24 億元**，毛利率 **63%**；營業利益：**47.97 億元**。\n- 2026Q1 營業費用合計增加，推銷管理費用 **18.20 億元**、研發費用 **8.07 億元**。\n- 2026/3 月底現金及短期投資 **91.43 億元**，存貨 **90.40 億元**，總資產 **546.70 億元**。\n- 存貨週轉天數 **172 天**，應收帳款週轉天數 **77 天**，應付帳款週轉天數 **90 天**；淨負債比維持 **Net Cash**。\n- 2026Q1 營運現金流入 **10.16 億元**，自由現金流 **-8.25 億元**。\n\n### 展望與成長利基\n- 管理層表示 **ATS／量測儀器** 今年仍可維持強勁表現，並提到 **AI server power** 需求持續。\n- **Battery cell / ESS** 相關貢獻預期自 **2026Q2** 開始逐步反映。\n- **半導體／Photonics** 業務今年除 transceiver 外，**CPO** 也可望成為增量來源。\n- 管理層提到部分客戶已完成 **scale-out / scale-up** 規劃，並收到相關 **PO**，其中某些插入點（insertion）已進入試產或導入階段。\n- 面對 SLT 需求與 cycle time 拉長，管理層表示「**正在考慮上修全年預測**」，但未揭露具體數字。\n- 產能方面提到既有二期規劃原本包含兩棟廠房，因中長期能見度提升，傾向保留完整容量配置。\n\n### 產品、客戶與市場位置\n- 營收成長主因為 **量測儀器／ATS** 與 **半導體／Photonics 測試解決方案**，管理層多次提到 AI server power、system level tester 與光通訊需求帶動。\n- 法說中多次提及 **CPO、SLT、AI server power、ESS、battery** 等新應用，顯示產品組合持續往高階應用延伸。\n- 管理層表示 **ATS／量測儀器** 今年仍可維持強勁表現，並提到 **AI server power** 需求持續。\n- **半導體／Photonics** 業務今年除 transceiver 外，**CPO** 也可望成為增量來源。\n- 管理層提到部分客戶已完成 **scale-out / scale-up** 規劃，並收到相關 **PO**，其中某些插入點（insertion）已進入試產或導入階段。\n- 管理層對 **季度季節性** 不提供明確判斷，並多次表示出貨可能因客戶時程而「**一次性集中**」。\n\n### 風險與不確定性\n- 簡報載明一般性 **forward-looking statements** 風險，未來實際結果可能與預期不同。\n- 管理層對 **季度季節性** 不提供明確判斷，並多次表示出貨可能因客戶時程而「**一次性集中**」。\n- **CPO／Photonics** 的貢獻時點與規模仍受客戶導入、試產進度與訂單確認影響。\n- **SLT** 與 AI 平台客戶需求強勁，但客戶組合、cycle time 與專案節奏可能影響後續認列。\n- 存貨金額與週轉天數上升，顯示供應鏈備料與在手庫存管理仍需持續觀察。\n- 營運現金流雖維持正值，但自由現金流為負，主因提及投資活動／固定收益金融工具配置。\n- **需人工確認**：簡報與口說皆提及 **ATS 2026Q1 YoY +145%**，但表格中「量測及自動化檢測設備」為 **QoQ +105%、YoY +145%**，口說也多次重複 +145%；數字一致，但需注意口語有時把 QoQ／YoY 混講。\n- **需人工確認**：簡報第 8 頁「**+ 量測事業體海外據點及測試設備相關子公司 2,288 (1%) 88% 5,155**」版面欄位對齊略不清，建議核對該列是 **占比、QoQ、YoY** 哪一欄。\n\n### Q&A 與管理層口氣\n- 問答聚焦於 **ATS 成長可持續性、毛利率組合、Photonics / CPO、SLT、Burn-in、ESS / power、產能規劃**。\n- 管理層表示 **ATS 高成長不會以每季 100% 的方式預期**，但今年整體仍看好。\n- 關於 **Photonics mix**，管理層認為 **CPO 不應低估**，但未提供明確占比。\n- 關於 **SLT**，管理層提到 **NVIDIA、AMD、Google** 等客戶需求，且部分客戶 cycle time 拉長、訂單增加。\n- 關於 **Burn-in**，已取得 **一家 C/S 客戶** 的新系統訂單，其他客戶仍在試用或導入中。\n- 管理層提到 **AI FT handler** 仍按進度推進，後續將在產品成果成熟時對外呈現。\n\n### 評分利基點\n- 加分主因：2026Q1 合併營收 **118.59 億元**，創歷年同期新高；較 2025Q4 成長 **38%**，較 2025Q1 成長 **73%**。；營收成長主因為 **量測儀器／ATS** 與 **半導體／Photonics 測試解決方案**，管理層多次提到 AI server power、system level tester 與光通訊需求帶動。；毛利率 **63%**，為單季次高；營業利益率 **40%**，稅後淨利 **39.48 億元**。。\n- 扣分或保留：簡報載明一般性 **forward-looking statements** 風險，未來實際結果可能與預期不同。；管理層對 **季度季節性** 不提供明確判斷，並多次表示出貨可能因客戶時程而「**一次性集中**」。；**CPO／Photonics** 的貢獻時點與規模仍受客戶導入、試產進度與訂單確認影響。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
