          "detailMarkdown": "## 2301 光寶科 詳細摘要\n\n### 判讀結論\n- 展望評價：中性偏正面（64 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對。\n- 評分依據：正向訊號 2、保守訊號 0。\n\n### 會議脈絡\n- 1Q26 營收 NT$434 億，年增約 19%，主要受惠 AI 基礎建設與雲端相關需求成長。\n- 管理層表示雲端/AIoT 事業為主要成長引擎，雲端相關營收年增超過七成。\n- 公司強調正加速海外布局與產能擴充，支撐 AI 電能管理、資料中心與系統整合需求。\n- 第二季展望偏向續強，管理層提到核心事業有機會較第一季更佳。\n- 會中亦說明美國與越南資本投資案，以及後續募資工具的多元化規劃。\n\n### 展望與利基\n- 2Q26 核心事業可望維持年、季雙成長，管理層表示第二季營運有機會優於第一季。\n- AI 電能管理系統升級持續推進，50V 整合式電源櫃關鍵模組進入量產。\n- 110kW Power Shelf 預計 6 月進入量產；33kW Power Shelf 需求強勁。\n- 800VDC Power Rack 預計於 3Q 完成驗證、4Q 開始量產；2.5kW DCDC Power Brick 預計 2H 量產。\n- 全年 AI 相關營收占比目標維持不變，管理層口徑為接近 30%。\n\n### 分數利基點\n- 2Q26 核心事業可望維持年、季雙成長，管理層表示第二季營運有機會優於第一季。\n- AI 電能管理系統升級持續推進，50V 整合式電源櫃關鍵模組進入量產。\n- 110kW Power Shelf 預計 6 月進入量產；33kW Power Shelf 需求強勁。\n- 800VDC Power Rack 預計於 3Q 完成驗證、4Q 開始量產；2.5kW DCDC Power Brick 預計 2H 量產。\n- 全年 AI 相關營收占比目標維持不變，管理層口徑為接近 30%。\n\n### 需要保留的疑慮\n- 目前摘要中未出現明顯負向或保守訊號，但仍需留意公司未量化揭露的部分。"
