          "detailMarkdown": "## 3016 嘉晶 詳細摘要\n\n### 判讀結論\n- 展望評價：正面看好（71 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對。\n- 評分依據：正向訊號 3、保守訊號 0。\n\n### 會議脈絡\n- 公司表示自 2026 年起，法說會頻率由每年一次調整為每年兩次，以利更即時揭露營運狀況。\n- 2026 Q1 受 AI Data Center Infrastructure 帶動，營運較去年同期明顯改善，並提到產品結構調整與成本控管帶來成效。\n- 新事業矽光子（Germany on Silicon / Ge/Si PD）已完成產品驗證並進入小量生產，視為未來重要新動能。\n- 管理層對 2026 全年及下半年營運態度偏正向，並預期 2026 Q2 營收較 Q1 可有明顯成長。\n- 公司強調 AI 相關應用、8 吋產能擴充、GaN / SiC 與矽光子為後續主要發展主軸。\n\n### 展望與利基\n- 2026 Q2 營收預期較 Q1 成長超過 20%。\n- 矽磊晶方面，AI power 需求強勁，8 吋需求高於預期，公司將加速 8 吋設備裝機與產能擴充。\n- GaN 方面，6 吋需求回溫且已由虧轉盈；8 吋已完成製程開發與客戶驗證，進入小量試產。\n- SiC 方面，6 吋營收維持穩定，8 吋已完成製程開發並陸續送樣，部分日系客戶驗證通過，Q2 已進入量產。\n- 矽光子方面，Ge/Si PD 已進入小量生產，後續將持續擴充產能以滿足 AI 高速傳輸供應鏈需求。\n\n### 分數利基點\n- 2026 Q2 營收預期較 Q1 成長超過 20%。\n- 矽磊晶方面，AI power 需求強勁，8 吋需求高於預期，公司將加速 8 吋設備裝機與產能擴充。\n- GaN 方面，6 吋需求回溫且已由虧轉盈；8 吋已完成製程開發與客戶驗證，進入小量試產。\n- SiC 方面，6 吋營收維持穩定，8 吋已完成製程開發並陸續送樣，部分日系客戶驗證通過，Q2 已進入量產。\n- 矽光子方面，Ge/Si PD 已進入小量生產，後續將持續擴充產能以滿足 AI 高速傳輸供應鏈需求。\n\n### 需要保留的疑慮\n- 目前摘要中未出現明顯負向或保守訊號，但仍需留意公司未量化揭露的部分。"
