          "detailMarkdown": "## 4166 友霖 詳細摘要\n\n### 判讀結論\n- 展望評價：中性偏正面（58 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對。\n- 評分依據：正向訊號 2、保守訊號 1。\n\n### 會議脈絡\n- 公司定位為從長期研發投入進入商業化與獲利收成期，並強調股東回饋與配息能力。\n- 核心策略聚焦兩大治療領域：**CNS（中樞神經系統）**與**CV/心血管**，搭配 505(b)(2) 與 P4/學名藥挑戰策略。\n- 對外市場以美國為核心，並延伸亞太等海外市場，強調外銷成長與通路重整。\n- 產品組合、製程優化與智慧製造被視為推動營運槓桿提升的主要來源。\n- 公司表示已完成多項商業化里程碑，並進一步朝 2026 年彌補累虧與啟動配息規劃推進。\n\n### 展望與利基\n- 2026 年目標之一為**完成累積虧損彌補**，並正式啟動股東配息計畫。\n- 持續聚焦 CNS、CV 兩大產品線，以特殊劑型與高門檻產品策略擴大營運規模。\n- 美國市場仍為海外成長核心，並透過經銷體系、標案與在地合作加速放量。\n- 2026 年將導入智慧製造與系統升級，以提升產能利用、縮短週期並改善品質。\n- 公司表示將於 2026 年發布首本永續經營報告。\n\n### 分數利基點\n- 美國市場仍為海外成長核心，並透過經銷體系、標案與在地合作加速放量。\n- 2026 年將導入智慧製造與系統升級，以提升產能利用、縮短週期並改善品質。\n\n### 需要保留的疑慮\n- 核心策略聚焦兩大治療領域：**CNS（中樞神經系統）**與**CV/心血管**，搭配 505(b)(2) 與 P4/學名藥挑戰策略。"
